from plib import *
T = '버블 정렬·정렬 알고리즘'
BUB = 'a = list(map(int, input().split()))\nn = len(a)\n'
P(T, 'k회전 뒤의 모습', 'I', '수열을 **내림차순** 버블 정렬한다. 버블 정렬은 왼쪽부터 이웃한 두 수를 비교하여 앞의 수가 더 작으면 교환하며, 한 회전이 끝나면 가장 작은 수가 맨 뒤에 자리 잡는다. `k` 회전을 마친 직후의 수열을 구하시오. (조기 종료는 하지 않는다)',
  '첫 줄에 `n k` (2 ≤ n ≤ 100, 0 ≤ k ≤ n-1), 둘째 줄에 n개의 정수(-1000 이상 1000 이하)가 주어진다.', '첫 줄에 k회전 직후의 수열을 공백으로 구분하여 출력한다. 둘째 줄에 그때까지 일어난 교환의 횟수를 출력한다.',
  'n, k = map(int, input().split())\na = list(map(int, input().split()))\nswaps = 0\nfor i in range(k):\n    for j in range(n - 1 - i):\n        if a[j] < a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\n            swaps += 1\nprint(*a)\nprint(swaps)',
  ['4 1\n2 5 1 4', '4 3\n2 5 1 4', '3 0\n1 2 3', '5 2\n1 2 3 4 5', '2 1\n-5 5', '6 3\n3 3 1 2 2 9'], gen=lambda r: (lambda n: f"{n} {r.randint(0,n-1)}\n{RL(r,n,-9,20)}")(r.randint(2,10)), cond=['`sort()`, `sorted()` 를 사용하지 말 것'])
P(T, '조기 종료 버블 정렬', 'I', '오름차순 버블 정렬에 **조기 종료**를 넣는다. 한 회전 동안 교환이 한 번도 일어나지 않으면 이미 정렬된 것이므로 그 회전을 끝으로 멈춘다. 회전은 최대 n-1 번이다.',
  '수열이 한 줄에 공백으로 구분되어 주어진다. (2개 이상 100개 이하, 각 수는 -1000 이상 1000 이하의 정수)', '회전이 끝날 때마다 그때의 수열을 한 줄씩 출력한다(교환이 없었던 마지막 회전도 출력한다). 마지막 줄에 수행한 회전 수와 총 비교 횟수를 공백으로 구분하여 출력한다.',
  BUB + 'rounds = 0\ncmps = 0\nfor i in range(n - 1):\n    swapped = False\n    for j in range(n - 1 - i):\n        cmps += 1\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\n            swapped = True\n    rounds += 1\n    print(*a)\n    if not swapped:\n        break\nprint(rounds, cmps)',
  ['1 2 4 3', '1 2 3 4 5', '5 4 3 2 1', '2 1', '1 2', '3 1 2 4 5 6'], gen=lambda r: RL(r, r.randint(2,9), -5, 15), cond=['교환 여부를 기록하는 변수(예: `swapped`)를 사용할 것'])
P(T, '정렬과 양 끝의 합', 'B', '수열을 오름차순 버블 정렬한 뒤, **첫 값과 끝 값의 합**을 구한다. 정렬하는 동안 교환이 몇 번 일어났는지도 센다.',
  '첫 줄에 `n` (1 ≤ n ≤ 100), 둘째 줄에 n개의 정수(-10000 이상 10000 이하)가 주어진다.', '첫 줄에 정렬된 수열, 둘째 줄에 첫 값과 끝 값의 합, 셋째 줄에 교환 횟수를 출력한다.',
  'n = int(input())\na = list(map(int, input().split()))\nswaps = 0\nfor i in range(n - 1):\n    for j in range(n - 1 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\n            swaps += 1\nprint(*a)\nprint(a[0] + a[-1])\nprint(swaps)',
  ['5\n4 2 7 1 5', '1\n9', '2\n2 1', '4\n1 2 3 4', '4\n4 3 2 1', '3\n-10000 10000 0'], gen=lambda r: (lambda n: f"{n}\n{RL(r,n,-20,20)}")(r.randint(1,12)), cond=['`sort()`, `sorted()`, `max()`, `min()` 을 사용하지 말 것'])
P(T, '선택 정렬 따라가기', 'I', '**선택 정렬**은 다음과 같이 동작한다. i = 0, 1, …, n-2 에 대해 차례로, i번째 칸부터 끝까지 중에서 **가장 작은 값**을 찾아 i번째 칸의 값과 교환한다. 가장 작은 값이 여러 개이면 가장 왼쪽 것을 고른다. 가장 작은 값이 이미 i번째 칸에 있으면 교환하지 않는다.',
  '수열이 한 줄에 공백으로 구분되어 주어진다. (2개 이상 100개 이하, 각 수는 -1000 이상 1000 이하의 정수)', '각 단계(i = 0 … n-2)가 끝날 때마다 수열을 한 줄씩 출력한다. 마지막 줄에 실제로 교환이 일어난 횟수를 출력한다.',
  BUB + 'swaps = 0\nfor i in range(n - 1):\n    m = i\n    for j in range(i + 1, n):\n        if a[j] < a[m]:\n            m = j\n    if m != i:\n        a[i], a[m] = a[m], a[i]\n        swaps += 1\n    print(*a)\nprint(swaps)',
  ['5 3 8 1', '1 2 3', '3 2 1', '2 1', '4 4 1 1', '9 -3 5 0 5 -3'], gen=lambda r: RL(r, r.randint(2,9), -5, 15), cond=['`sort()`, `sorted()`, `min()`, `index()` 를 사용하지 말 것'])
P(T, '수행평가 순위표', 'I', '학생들의 이름과 점수가 주어진다. 점수가 높은 순서로 정렬하되, **점수가 같으면 먼저 입력된 학생이 앞**에 오도록 한다.',
  '첫 줄에 `n` (1 ≤ n ≤ 100), 이어서 n줄에 `이름 점수` 가 주어진다. (점수는 0 이상 100 이하의 정수, 이름은 서로 다르다)', '정렬된 순서대로 `이름 점수` 를 한 줄씩 출력한다.',
  'n = int(input())\nnames = []\nscores = []\nfor _ in range(n):\n    a, b = input().split()\n    names.append(a)\n    scores.append(int(b))\nfor i in range(n - 1):\n    for j in range(n - 1 - i):\n        if scores[j] < scores[j + 1]:\n            scores[j], scores[j + 1] = scores[j + 1], scores[j]\n            names[j], names[j + 1] = names[j + 1], names[j]\nfor i in range(n):\n    print(names[i], scores[i])',
  ['4\n민 80\n솔 95\n준 80\n하 70', '1\nA 0', '3\nA 50\nB 50\nC 50', '3\nA 1\nB 2\nC 3', '5\nE 100\nD 0\nC 100\nB 0\nA 100', '2\nx 9\ny 10'], gen=lambda r: (lambda n: f"{n}\n" + "\n".join(f"s{i} {r.randint(0,5)*10}" for i in range(n)))(r.randint(2,9)), cond=['`sort()`, `sorted()` 를 사용하지 말고 버블 정렬로 구현할 것', '힌트: 버블 정렬에서 **앞이 더 작을 때만** 교환하면 같은 점수의 순서가 유지된다'])
P(T, '달리기 등수 매기기', 'I', '달리기 기록(초)이 주어진다. 기록이 짧을수록 등수가 높다. 각 학생의 등수는 **자기보다 기록이 짧은 학생의 수 + 1** 이다. (같은 기록은 같은 등수)',
  '첫 줄에 `n` (1 ≤ n ≤ 500), 둘째 줄에 n개의 기록(1 이상 10000 이하의 정수)이 주어진다.', '첫 줄에 입력 순서대로 각 학생의 등수를 공백으로 구분하여 출력한다. 둘째 줄에 1등인 학생의 수를 출력한다.',
  'n = int(input())\na = list(map(int, input().split()))\nrank = []\nfor i in range(n):\n    r = 1\n    for j in range(n):\n        if a[j] < a[i]:\n            r += 1\n    rank.append(r)\nprint(*rank)\ncnt = 0\nfor r in rank:\n    if r == 1:\n        cnt += 1\nprint(cnt)',
  ['5\n15 12 18 12 20', '1\n100', '3\n7 7 7', '4\n4 3 2 1', '4\n1 2 3 4', '6\n10 10 9 9 8 8'], gen=lambda r: (lambda n: f"{n}\n{RL(r,n,10,16)}")(r.randint(1,12)))
P(T, '정렬 상태 판별', 'B', '수열이 어떤 상태인지 판별한다. 모든 이웃한 두 수에 대해 뒤의 수가 앞의 수보다 **크거나 같으면** 오름차순, **작거나 같으면** 내림차순이다. 모든 수가 같으면 둘 다에 해당한다.',
  '첫 줄에 `n` (1 ≤ n ≤ 1000), 둘째 줄에 n개의 정수가 주어진다.', '모든 수가 같으면(또는 수가 하나이면) `모두 같음`, 오름차순이면 `오름차순`, 내림차순이면 `내림차순`, 어느 것도 아니면 `정렬 안 됨` 을 출력한다. `정렬 안 됨` 인 경우 둘째 줄에 오름차순이 **처음으로 깨지는 위치**(뒤의 수가 더 작은 첫 번째 쌍에서 뒤의 수의 위치, 1부터)를 출력한다.',
  'n = int(input())\na = list(map(int, input().split()))\nup = True\ndown = True\nfirst = 0\nfor i in range(1, n):\n    if a[i] < a[i - 1]:\n        up = False\n        if first == 0:\n            first = i + 1\n    if a[i] > a[i - 1]:\n        down = False\nif up and down:\n    print("모두 같음")\nelif up:\n    print("오름차순")\nelif down:\n    print("내림차순")\nelse:\n    print("정렬 안 됨")\n    print(first)',
  ['5\n1 2 2 3 9', '4\n9 7 7 1', '3\n4 4 4', '1\n5', '5\n1 3 2 4 5', '4\n5 6 1 2', '2\n2 1', '2\n1 2'], gen=lambda r: (lambda n: f"{n}\n{RL(r,n,1,4)}")(r.randint(2,7)))
P(T, '교환 장면 기록', 'I', '오름차순 버블 정렬의 **1회전**만 수행하면서, 교환이 일어날 때마다 교환한 두 값을 기록한다.',
  '수열이 한 줄에 공백으로 구분되어 주어진다. (2개 이상 100개 이하의 정수)', '교환이 일어날 때마다 `큰값 <-> 작은값` 을 한 줄씩 출력한다(교환 전 앞에 있던 값을 먼저 쓴다). 교환이 한 번도 없으면 `교환 없음` 을 출력한다. 마지막 줄에 1회전 뒤의 수열을 출력한다.',
  BUB + 'cnt = 0\nfor j in range(n - 1):\n    if a[j] > a[j + 1]:\n        print(f"{a[j]} <-> {a[j + 1]}")\n        a[j], a[j + 1] = a[j + 1], a[j]\n        cnt += 1\nif cnt == 0:\n    print("교환 없음")\nprint(*a)',
  ['5 3 8 1', '1 2 3', '3 2 1', '2 2', '9 1 1 1', '1 5 2 6 3'], gen=lambda r: RL(r, r.randint(2,9), 1, 12))
P(T, 'k번째로 큰 수', 'I', '수열에서 `k` 번째로 큰 수를 구한다. 같은 수가 여러 개 있으면 **각각 따로** 센다. (예: `5 5 3` 에서 2번째로 큰 수는 5)',
  '첫 줄에 `n k` (1 ≤ k ≤ n ≤ 200), 둘째 줄에 n개의 정수(-10^6 이상 10^6 이하)가 주어진다.', 'k번째로 큰 수를 출력한다.',
  'n, k = map(int, input().split())\na = list(map(int, input().split()))\nfor i in range(k):\n    for j in range(n - 1 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\nprint(a[n - k])',
  ['5 2\n3 9 4 9 1', '1 1\n7', '3 3\n5 5 3', '3 2\n5 5 3', '4 1\n-1 -2 -3 -4', '6 4\n10 20 30 40 50 60'], gen=lambda r: (lambda n: f"{n} {r.randint(1,n)}\n{RL(r,n,-9,9)}")(r.randint(1,12)), cond=['`sort()`, `sorted()`, `max()` 를 사용하지 말 것', '힌트: 버블 정렬을 **k회전만** 하면 뒤쪽 k칸이 확정된다'])
P(T, '두 줄 합치기', 'I', '키 순서(오름차순)로 서 있는 두 줄의 학생들을 **키 순서를 유지하며** 한 줄로 합친다. 키가 같으면 첫 번째 줄의 학생이 앞에 선다.',
  '첫 줄에 첫 번째 줄의 키들이, 둘째 줄에 두 번째 줄의 키들이 오름차순으로 주어진다. (각 줄 1명 이상 500명 이하, 키는 100 이상 250 이하의 정수)', '합친 줄을 공백으로 구분하여 출력한다. 둘째 줄에, 합친 줄에서 **두 번째 줄 출신** 학생들의 위치(1부터)를 공백으로 구분하여 출력한다.',
  'a = list(map(int, input().split()))\nb = list(map(int, input().split()))\ni = 0\nj = 0\nout = []\npos = []\nwhile i < len(a) or j < len(b):\n    if j >= len(b) or (i < len(a) and a[i] <= b[j]):\n        out.append(a[i])\n        i += 1\n    else:\n        out.append(b[j])\n        pos.append(len(out) + 1)\n        j += 1\nprint(*out)\nprint(*[p - 1 for p in pos])',
  ['150 160 170\n155 160 180', '100\n250', '250\n100', '150 150\n150 150', '160 170 180\n150', '150\n160 170 180'], gen=lambda r: " ".join(map(str, sorted(r.randint(150,160) for _ in range(r.randint(1,6))))) + "\n" + " ".join(map(str, sorted(r.randint(150,160) for _ in range(r.randint(1,6))))), cond=['`sort()`, `sorted()` 를 사용하지 말 것'])

T = '딕셔너리 활용'
P(T, '마트 계산과 쿠폰', 'I', '마트 가격표와 장바구니가 주어진다. 장바구니에 같은 물건이 여러 번 담기면 수량을 합친다. 가격표에 없는 물건은 계산하지 않는다.\n\n계산이 끝나면 쿠폰을 적용한다. 쿠폰이 `P10` 이면 합계의 10% 를 할인하고(원 미만 버림), `M3000` 이면 합계가 20000원 이상일 때만 3000원을 뺀다. `NONE` 이면 할인이 없다.',
  '첫 줄에 가격표의 물건 수 `n` (1 ≤ n ≤ 50), 이어서 n줄에 `물건 가격` 이 주어진다. 다음 줄에 담은 횟수 `m` (0 ≤ m ≤ 100), 이어서 m줄에 `물건 수량` 이 주어진다. 마지막 줄에 쿠폰 종류가 주어진다.', '계산한 물건을 **가격표 순서대로** `물건 수량개 금액원` 으로 한 줄씩 출력한다(담지 않은 물건은 출력하지 않는다). 다음 줄에 `합계 N원`, 그다음 줄에 `결제 N원` 을 출력한다.',
  'n = int(input())\nprice = {}\nfor _ in range(n):\n    k, v = input().split()\n    price[k] = int(v)\nm = int(input())\ncart = {}\nfor _ in range(m):\n    k, c = input().split()\n    if k in price:\n        cart[k] = cart.get(k, 0) + int(c)\ncoupon = input()\ntotal = 0\nfor k in price:\n    if k in cart:\n        print(f"{k} {cart[k]}개 {price[k] * cart[k]}원")\n        total += price[k] * cart[k]\nprint(f"합계 {total}원")\npay = total\nif coupon == "P10":\n    pay = total - total // 10\nelif coupon == "M3000" and total >= 20000:\n    pay = total - 3000\nprint(f"결제 {pay}원")',
  ['3\n우유 1500\n빵 2000\n사과 800\n4\n빵 1\n우유 2\n과자 3\n우유 1\nP10', '2\n쌀 19999\n김 1\n2\n쌀 1\n김 1\nM3000', '2\n쌀 19999\n김 1\n1\n쌀 1\nM3000', '1\n물 500\n0\nNONE', '2\na 333\nb 7\n3\nb 1\na 1\nb 2\nP10', '1\n껌 505\n1\n껌 1\nP10'])
P(T, '도서관 대출 한도', 'I', '도서관은 책마다 보유 수량이 있고, 회원은 한 사람당 **동시에 2권까지** 빌릴 수 있다. 같은 책을 한 사람이 두 권 빌릴 수는 없다.\n\n`대출 회원 책` : 없는 책이면 `없는 책`, 그 회원이 이미 그 책을 빌렸으면 `중복 대출`, 이미 2권을 빌렸으면 `한도 초과`, 남은 수량이 0 이면 `재고 없음`, 그 밖에는 `대출 완료` 이다. (앞에 적힌 것부터 검사)\n`반납 회원 책` : 그 회원이 그 책을 빌린 상태가 아니면 `반납 오류`, 맞으면 `반납 완료` 이다.',
  '첫 줄에 책의 종류 수 `n` (1 ≤ n ≤ 20), 이어서 n줄에 `책 수량` 이 주어진다. 다음 줄부터 명령이 한 줄씩 주어지며 마지막 줄은 `종료` 이다. (명령은 200개 이하)', '명령마다 결과 메시지를 한 줄씩 출력한다. `종료` 뒤에 책을 입력 순서대로 `책: 남은수량` 으로 출력한다.',
  'n = int(input())\nstock = {}\nfor _ in range(n):\n    b, c = input().split()\n    stock[b] = int(c)\nloan = {}\nwhile True:\n    line = input().split()\n    if line[0] == "종료":\n        break\n    cmd, who, book = line\n    if who not in loan:\n        loan[who] = []\n    if cmd == "대출":\n        if book not in stock:\n            print("없는 책")\n        elif book in loan[who]:\n            print("중복 대출")\n        elif len(loan[who]) >= 2:\n            print("한도 초과")\n        elif stock[book] == 0:\n            print("재고 없음")\n        else:\n            stock[book] -= 1\n            loan[who].append(book)\n            print("대출 완료")\n    else:\n        if book in loan[who]:\n            loan[who].remove(book)\n            stock[book] += 1\n            print("반납 완료")\n        else:\n            print("반납 오류")\nfor b in stock:\n    print(f"{b}: {stock[b]}")',
  ['3\n파이썬 1\n수학 2\n물리 1\n대출 민 파이썬\n대출 솔 파이썬\n대출 민 수학\n대출 민 물리\n반납 민 파이썬\n대출 솔 파이썬\n종료', '1\nA 1\n종료', '1\nA 2\n대출 x A\n대출 x A\n반납 x A\n반납 x A\n대출 x B\n종료', '2\nA 0\nB 5\n대출 p A\n대출 p B\n대출 q B\n반납 q A\n반납 r B\n종료', '3\na 1\nb 1\nc 1\n대출 k a\n대출 k b\n대출 k c\n대출 k d\n반납 k a\n대출 k c\n종료', '1\n책 1\n대출 가 책\n대출 나 책\n반납 가 책\n대출 나 책\n종료'])
P(T, '가장 많이 나온 단어', 'I', '문장에서 각 단어가 몇 번 나왔는지 세고, 가장 많이 나온 단어를 찾는다. 대소문자는 구분하지 않는다. 가장 많이 나온 단어가 여러 개이면 **문장에서 먼저 등장한** 단어를 고른다.',
  '영어 단어들이 공백으로 구분된 문장이 한 줄에 주어진다. (단어 1개 이상 500개 이하)', '첫 줄에 서로 다른 단어의 수를 출력한다. 둘째 줄에 가장 많이 나온 단어(소문자)와 그 횟수를 공백으로 구분하여 출력한다. 셋째 줄에 **한 번만** 나온 단어의 수를 출력한다.',
  'words = input().lower().split()\ncnt = {}\nfor w in words:\n    cnt[w] = cnt.get(w, 0) + 1\nbest = ""\nfor w in cnt:\n    if best == "" or cnt[w] > cnt[best]:\n        best = w\nprint(len(cnt))\nprint(best, cnt[best])\nonce = 0\nfor w in cnt:\n    if cnt[w] == 1:\n        once += 1\nprint(once)',
  ['the cat and The dog and THE bird', 'hello', 'a b a b', 'b a a b', 'One two three', 'Go go GO gO stop'], gen=lambda r: " ".join(r.choice(["ai", "py", "gsa", "Py", "AI", "nest"]) for _ in range(r.randint(1,20))))
P(T, '출석부 집계', 'B', '여러 날의 출석 기록이 주어진다. 하루에 한 줄씩, 그날 출석한 학생들의 이름이 적혀 있다. 학생별 출석 횟수를 구하시오.',
  '첫 줄에 날 수 `d` (1 ≤ d ≤ 30), 이어서 d줄에 그날 출석한 학생들의 이름이 공백으로 구분되어 주어진다. (하루에 1명 이상 30명 이하, 하루 안에서 이름은 중복되지 않는다)', '학생을 **처음 등장한 순서대로** `이름 횟수` 로 한 줄씩 출력한다. 마지막 줄에 하루도 빠지지 않은 학생의 수를 출력한다.',
  'd = int(input())\ncnt = {}\nfor _ in range(d):\n    for name in input().split():\n        cnt[name] = cnt.get(name, 0) + 1\nfull = 0\nfor name in cnt:\n    print(name, cnt[name])\n    if cnt[name] == d:\n        full += 1\nprint(full)',
  ['3\n민 솔 준\n솔 민\n하 민', '1\nA', '2\nA B\nC D', '2\nA B\nB A', '4\nx\nx\nx\ny', '3\na b c\nc b a\nb'])
P(T, '자판기 재고 관리', 'I', '자판기에 음료별 가격과 재고가 있다. 손님이 돈을 넣고 음료를 고른다.\n\n없는 음료이면 `없는 음료`, 재고가 0 이면 `품절`, 넣은 돈이 가격보다 적으면 `금액 부족` 이며 이 세 경우에는 넣은 돈을 그대로 돌려준다. 살 수 있으면 재고를 1 줄이고 `음료 거스름돈 N원` 을 출력한다.',
  '첫 줄에 음료의 종류 수 `n` (1 ≤ n ≤ 20), 이어서 n줄에 `음료 가격 재고` 가 주어진다. 다음 줄에 손님 수 `m` (1 ≤ m ≤ 100), 이어서 m줄에 `넣은돈 음료` 가 주어진다.', '손님마다 결과를 한 줄씩 출력한다. 마지막에 `매출 N원` 을 출력하고, 그다음 줄에 품절된 음료의 이름을 입력 순서대로 공백으로 구분하여 출력한다(없으면 `품절 없음`).',
  'n = int(input())\nprice = {}\nstock = {}\nfor _ in range(n):\n    a, b, c = input().split()\n    price[a] = int(b)\n    stock[a] = int(c)\nm = int(input())\nsales = 0\nfor _ in range(m):\n    money, d = input().split()\n    money = int(money)\n    if d not in price:\n        print("없는 음료")\n    elif stock[d] == 0:\n        print("품절")\n    elif money < price[d]:\n        print("금액 부족")\n    else:\n        stock[d] -= 1\n        sales += price[d]\n        print(f"{d} 거스름돈 {money - price[d]}원")\nout = []\nfor d in stock:\n    if stock[d] == 0:\n        out.append(d)\nprint(f"매출 {sales}원")\nif out:\n    print(*out)\nelse:\n    print("품절 없음")',
  ['2\n콜라 1200 1\n물 800 2\n4\n1000 콜라\n2000 콜라\n1500 콜라\n800 주스', '1\n물 500 1\n1\n500 물', '1\n물 500 0\n1\n500 물', '2\na 100 5\nb 100 5\n3\n99 a\n100 b\n101 c', '3\nx 10 1\ny 20 1\nz 30 1\n3\n30 z\n20 y\n10 x', '1\n차 700 2\n3\n1000 차\n700 차\n700 차'])
P(T, '성적 관리 명령어', 'I', '학생 점수를 딕셔너리로 관리한다.\n\n`ADD 이름 점수` : 새 학생을 등록한다. 이미 있으면 `이미 있음`. `SET 이름 점수` : 점수를 고친다. 없으면 `없는 학생`. `DEL 이름` : 삭제한다. 없으면 `없는 학생`. `GET 이름` : 점수를 출력한다. 없으면 `없는 학생`. `TOP` : 점수가 가장 높은 학생의 이름과 점수를 출력한다. 동점이면 먼저 등록된 학생이다. 학생이 없으면 `학생 없음`.',
  '첫 줄에 명령 수 `q` (1 ≤ q ≤ 200), 이어서 q줄에 명령이 주어진다. 점수는 0 이상 100 이하의 정수이다.', '`GET` 과 `TOP` 의 결과, 그리고 오류 메시지를 한 줄씩 출력한다. 성공한 `ADD`, `SET`, `DEL` 은 아무것도 출력하지 않는다. 마지막 줄에 남은 학생 수를 출력한다.',
  'q = int(input())\nd = {}\nfor _ in range(q):\n    c = input().split()\n    if c[0] == "ADD":\n        if c[1] in d:\n            print("이미 있음")\n        else:\n            d[c[1]] = int(c[2])\n    elif c[0] == "TOP":\n        if not d:\n            print("학생 없음")\n        else:\n            best = ""\n            for k in d:\n                if best == "" or d[k] > d[best]:\n                    best = k\n            print(best, d[best])\n    elif c[1] not in d:\n        print("없는 학생")\n    elif c[0] == "SET":\n        d[c[1]] = int(c[2])\n    elif c[0] == "DEL":\n        del d[c[1]]\n    else:\n        print(d[c[1]])',
  ['7\nADD 민 80\nADD 솔 95\nADD 민 70\nSET 준 50\nGET 민\nTOP\nDEL 솔', '1\nTOP', '4\nADD a 50\nADD b 50\nTOP\nDEL c', '6\nADD a 1\nSET a 100\nGET a\nDEL a\nGET a\nTOP', '5\nADD x 0\nADD y 0\nDEL x\nTOP\nGET y', '3\nGET q\nSET q 1\nDEL q'])
