  'n = int(input())\nvotes = input().split()\ncnt = {}\nfor v in votes:\n    cnt[v] = cnt.get(v, 0) + 1\nbest = 0\nfor k in cnt:\n    print(k, cnt[k])\n    if cnt[k] > best:\n        best = cnt[k]\ntops = []\nfor k in cnt:\n    if cnt[k] == best:\n        tops.append(k)\nif len(tops) == 1 and best * 2 > n:\n    print("당선", tops[0])\nelse:\n    print("결선 투표")',
